const Sidebar = () => {
  return (
    <aside className="w-64 bg-white border-r p-4">
      <nav className="space-y-2">
        <a href="#" className="block text-gray-700 hover:text-purple-600">Dashboard</a>
        <a href="#" className="block text-gray-700 hover:text-purple-600">Projects</a>
        <a href="#" className="block text-gray-700 hover:text-purple-600">Settings</a>
      </nav>
    </aside>
  );
};

export default Sidebar;
